sys_script.script:
(function executeRule(current, previous) {

    try {
        var participantAssignmentSysId = current.getValue('participant_assignment');
        var planAssignmentSysId = current.getUniqueValue();

        // No Participant Assignment attached → allow delete
        if (!participantAssignmentSysId)
            return;

        var participantGR = new GlideRecordSecure('x_ctans_incentnow_participant_assignment');

        if (!participantGR.get(participantAssignmentSysId)) {
            gs.addErrorMessage('The related Participant Assignment could not be found.');
            current.setAbortAction(true);
            return;
        }

        // Delete allowed only when Participant Assignment is Draft
        if (participantGR.getValue('status') != 'draft') {
            gs.addErrorMessage(
                'Plan Assignment cannot be deleted because the related Participant Assignment is not in Draft state.'
            );
            current.setAbortAction(true);
            return;
        }

        // Delete related Quota Assignments first
        var quotaAssignmentGR = new GlideRecordSecure('x_ctans_incentnow_user_quota_assignment');
        quotaAssignmentGR.addQuery('plan_assignment', planAssignmentSysId);
        quotaAssignmentGR.query();

        while (quotaAssignmentGR.next())
            quotaAssignmentGR.deleteRecord();

    } catch (e) {
        gs.error(
            '[IncentIQ Plan Assignment] Delete validation failed. ' +
            'Plan Assignment=' + current.getUniqueValue() +
            ', Error=' + e.message
        );

        gs.addErrorMessage(
            'Plan Assignment could not be deleted because related Quota Assignments could not be removed.'
        );

        current.setAbortAction(true);
    }

})(current, previous);
